.dpt-print:hover{background:#16263F}
.dpt-controls{display:flex;gap:.8rem;flex-wrap:wrap;margin-bottom:1rem}
.dpt-controls .fld{flex:1;min-width:180px}
.dpt-controls label{display:block;font-size:1.25rem;font-weight:600;margin-bottom:.3rem}
