.dpt-head .t{font-size:1.95rem;font-weight:800;display:block}
.dpt-head .s{font-size:1.35rem;color:#64748b}
.dpt-head .s b{color:#16263F}
.dpt-grid{display:grid;grid-template-columns:repeat(10,1fr);gap:.35rem;margin:0 auto;max-width:520px}
.dpt-box{aspect-ratio:1/1;border:2px solid #1E3A5F;border-radius:5px;display:flex;align-items:center;justify-content:center;font-size:1rem;color:#c9d3e0}
